create table if not exists users (id bigint generated by default as identity primary key,email text unique not null,password text not null,name text default '',role text not null);
create table if not exists subjects (id bigint generated by default as identity primary key,owner_id bigint references users(id),name text not null,code text unique not null,created_at timestamptz default now());
create table if not exists enrollments (subject_id bigint references subjects(id),student_id bigint references users(id),joined_at timestamptz default now(),primary key(subject_id,student_id));
create table if not exists attendance (id bigint generated by default as identity primary key,subject_id bigint references subjects(id),student_id bigint references users(id),date date not null,present boolean default false,source text default 'face',unique(subject_id,student_id,date));
create index if not exists attendance_subject_date on attendance(subject_id,date);
insert into storage.buckets(id,name,public) values ('face-photos','face-photos',false) on conflict do nothing;
